from pathlib import Path
code='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    counts = {}
    for row in out:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    # Find each maximal diagonal run of at least two matching non-background cells.
    for dr, dc in ((1, 1), (1, -1)):
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == bg:
                    continue
                pr, pc = r-dr, c-dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                    continue
                run = [(r,c)]
                rr, cc = r+dr, c+dc
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    run.append((rr,cc)); rr += dr; cc += dc
                if len(run) < 2:
                    continue
                # Extend only along a clear ray; an existing non-background marker
                # blocks that side of the diagonal.
                for sr, sc in ((-dr,-dc),(dr,dc)):
                    er, ec = (run[0] if sr < 0 or (sr == -dr and sc == -dc) else run[-1])
                    # side is chosen explicitly by whether it precedes the run
                    if (sr,sc) == (-dr,-dc):
                        er,ec=run[0]
                    else:
                        er,ec=run[-1]
                    cells=[]; y,x=er+sr,ec+sc; clear=True
                    while 0 <= y < h and 0 <= x < w:
                        if grid[y][x] != bg:
                            clear=False; break
                        cells.append((y,x)); y+=sr; x+=sc
                    if clear:
                        for y,x in cells: out[y][x]=color
    return out
'''
